head.script:
scwin.createWindow = function() {
    var ws_s = "<input class=\"sp11\" value=\"";
    var ws_m = "subTitle";
    var ws_e = "\"/>";
    var c_cnt = 1;
    var c_subName = "windowContainer_spa_SKT-575_(WSQ-1155)_sub";
    var c_xmlName = ".xml";
    for (var i = 1; i <= c_cnt; i++) {
        // createWindow = function(title, iconUrl, src , windowTitle , windowId ,openAction, closeAction, windowTooltip, windowHeaderHTML)
        var windowHeaderHTML = ws_s + ws_m + i + ws_e;
        windowContainer1.createWindow(c_subName + i, null, c_subName + i + c_xmlName, null, null, "existWindow",
            null, null, windowHeaderHTML);
    }
}
scwin.setMenu = function(dataArr) {
    /*
     * @description nameLayerMenu 속성 사용시에 메뉴목록을 동적으로 설정합니다. 
     * @param       <Array:Y> arrData 메뉴목록을 설정할 array 데이터
     * @param       <Number:N> height 메뉴의 높이값  
     */
    windowContainer1.setMenu(dataArr, dataArr.length * 21);
}
scwin.windowContainer1_onmenuopen = function(windowId) {
    if (windowContainer1.isMultiView()) {
        scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "단일 뷰로 보기", "공유하기"]);
    } else {
        if (windowId === windowContainer1.getSelectedWindowId()) {
            scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "공유하기"]);
        } else {
            scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "멀티 뷰로 보기", "공유하기"]);
        }
    }
}
scwin.windowContainer1_onmenuclick = function(windowId, selectedItem) {
    switch (selectedItem) {
        case "화면 닫기":
            windowContainer1.closeWindow(windowId);
            break;
        case "듀얼 모니터로 보기":
            // 듀얼모니터로 보도록 함수 붙이면 됨.
            break;
        case "멀티 뷰로 보기":
            windowContainer1.setMultiView(windowId);
            break;
        case "단일 뷰로 보기":
            windowContainer1.setSingleView(windowId);
            break;
        case "공유하기":
            // 공유하기 관련 로직 작성
            break;
    }
}
scwin.doInit = function() {
    this.createWindow();
    this.setMenu(["화면 닫기", "듀얼 모니터로 보기", "멀티 뷰로 보기", "공유하기"]);
}
scwin.trigger1_onclick = function() {
    scwin.createWindow();
}
scwin.trigger2_onclick = function() {
    windowContainer1.doCloseAll();
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'windowContainer1_subWindow1').style.display == 'none';
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'windowContainer1_subWindow1').style.display == 'block';
}
scwin.checkVal2 = function() {
    return document.getElementsByClassName('sp11')[0].value == 'subTitle1';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step  1. 샘플파일을 실행한 후 'closeWindow'클릭 후 'createWindows'를 클릭한다.-   After running the sample file, click 'closeWindow' and then 'createWindows'. 	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    //Verify  1. windowContainer창이 닫히고 다시 열린다. 이때 windowContainer창의 Header영역이 정상적으로 보여진다.(이전에는 보여지지 않음)-The windowContainer window is closed and reopened. At this time, the header area of the windowContainer window is displayed normally (not shown previously).
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.doInit();
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    //End uniTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
